mapper.select:
SELECT activity_date FROM (
  SELECT DATE(created_at) AS activity_date FROM practice_attempts WHERE student_id=#{studentId}
  UNION SELECT DATE(created_at) FROM conversations WHERE student_id=#{studentId}
  UNION SELECT DATE(scheduled_at) FROM therapy_sessions WHERE student_id=#{studentId} AND status='COMPLETED'
) activity_days ORDER BY activity_date DESC

SELECT session_id AS sessionId, title, DATE_FORMAT(scheduled_at,'%Y-%m-%dT%H:%i:%s') AS scheduledAt,
  DATE_FORMAT(scheduled_at,'%Y-%m-%d') AS date, status, summary,
  (status='COMPLETED') AS done
FROM therapy_sessions WHERE student_id=#{studentId}
AND status=#{status}
ORDER BY scheduled_at DESC, session_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT homework_id AS homeworkId,homework_id AS id,title,type,description,target_minutes AS targetMinutes,
  DATE_FORMAT(due_date,'%Y-%m-%d') AS dueDate,status,(status='COMPLETED') AS done
FROM homeworks WHERE student_id=#{studentId}
ORDER BY CASE WHEN status='COMPLETED' THEN 1 ELSE 0 END,due_date,homework_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT homework_id AS homeworkId,homework_id AS id,title,type,description,target_minutes AS targetMinutes,
  DATE_FORMAT(due_date,'%Y-%m-%d') AS dueDate,status,(status='COMPLETED') AS done
FROM homeworks WHERE student_id=#{studentId} AND homework_id=#{homeworkId}

SELECT session_id AS sessionId, title, DATE_FORMAT(scheduled_at,'%Y-%m-%dT%H:%i:%s') AS scheduledAt,
  DATE_FORMAT(scheduled_at,'%Y-%m-%d') AS date, status, summary, (status='COMPLETED') AS done
FROM therapy_sessions WHERE student_id=#{studentId} AND session_id=#{sessionId}

SELECT exercise_id AS id,exercise_id AS exerciseId,title,title AS label,instruction,input_type AS inputType,c.color
FROM exercises e JOIN practice_categories c ON c.category_id=e.category_id
WHERE e.category_id=#{categoryId} AND e.active=TRUE ORDER BY e.sort_order LIMIT #{limit} OFFSET #{offset}

SELECT c.conversation_id AS conversationId,c.topic,c.status,c.created_at AS createdAt,c.updated_at AS updatedAt,
  (SELECT content FROM conversation_messages m WHERE m.conversation_id=c.conversation_id ORDER BY m.message_id DESC LIMIT 1) AS lastMessage
FROM conversations c WHERE c.student_id=#{studentId} ORDER BY c.updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT speaker,content,feedback,created_at AS createdAt FROM (
  SELECT message_id,speaker,content,feedback,created_at FROM conversation_messages
  WHERE conversation_id=#{conversationId} ORDER BY message_id DESC LIMIT #{limit}
) recent ORDER BY message_id ASC
